-- ============================================================================
-- TAHFIZH V88 — Tiga template raport bawaan dengan lima komponen utama
-- ============================================================================
-- Template bawaan developer kini tepat tiga: Raport 1 Kolom, 2 Kolom, 3 Kolom.
-- Isi utama semuanya sama: tartil Al-Qur’an, tahfidz Al-Qur’an, hadits pilihan,
-- doa harian, dan presensi. Tabel Nilai hanya mencetak modul yang tercantum di
-- props.modules (urutan sesuai daftar).
-- Salinan milik lembaga berdiri sendiri; migrasi ini tidak mengubahnya.
-- Idempoten: insert bila belum ada, lalu selalu disamakan dengan layout ini.
-- ============================================================================

-- Lepas penanda utama bawaan lebih dulu agar indeks unik (satu contoh utama) aman.
update public.report_templates set is_primary = false
 where tenant_id is null and is_primary;

insert into public.report_templates (tenant_id, name, description, paper, orientation, layout)
select null, 'Raport 1 Kolom', 'Satu kolom dari atas ke bawah: identitas santri, capaian tartil, tahfidz, hadits dan doa harian, presensi, lalu catatan guru.', 'A4', 'PORTRAIT', '{"pages":[{"components":[{"id":"a1-box","type":"BOX","x":40,"y":32,"w":714,"h":112,"z":1,"locked":false,"hidden":false,"style":{"background":"#eff6ff","borderColor":"#dbeafe","radius":14},"props":{}},{"id":"a2-logo","type":"LOGO","x":54,"y":44,"w":88,"h":88,"z":2,"locked":false,"hidden":false,"style":{},"props":{}},{"id":"a3-institution_name","type":"INSTITUTION_NAME","x":160,"y":48,"w":570,"h":28,"z":3,"locked":false,"hidden":false,"style":{"fontSize":18,"bold":true,"align":"left"},"props":{}},{"id":"a4-institution_address","type":"INSTITUTION_ADDRESS","x":160,"y":80,"w":570,"h":22,"z":4,"locked":false,"hidden":false,"style":{"fontSize":10,"align":"left"},"props":{}},{"id":"a5-institution_contact","type":"INSTITUTION_CONTACT","x":160,"y":104,"w":570,"h":20,"z":5,"locked":false,"hidden":false,"style":{"fontSize":9,"align":"left"},"props":{}},{"id":"a6-divider","type":"DIVIDER","x":40,"y":156,"w":714,"h":6,"z":6,"locked":false,"hidden":false,"style":{"borderColor":"#1d4ed8"},"props":{"thickness":3}},{"id":"a7-report_title","type":"REPORT_TITLE","x":40,"y":176,"w":714,"h":32,"z":7,"locked":false,"hidden":false,"style":{"fontSize":18,"bold":true,"align":"center"},"props":{}},{"id":"a8-academic_year","type":"ACADEMIC_YEAR","x":40,"y":210,"w":714,"h":18,"z":8,"locked":false,"hidden":false,"style":{"fontSize":11,"align":"center"},"props":{}},{"id":"a9-semester","type":"SEMESTER","x":40,"y":228,"w":714,"h":18,"z":9,"locked":false,"hidden":false,"style":{"fontSize":11,"align":"center"},"props":{}},{"id":"a10-section_heading","type":"SECTION_HEADING","x":40,"y":262,"w":714,"h":22,"z":10,"locked":false,"hidden":false,"style":{"fontSize":11,"color":"#1d4ed8","borderColor":"#dbeafe"},"props":{"text":"Identitas Santri"}},{"id":"a11-student_identity","type":"STUDENT_IDENTITY","x":40,"y":290,"w":714,"h":8